  "tool": "edit_file",
  "args": {
    "path": "code/analyze_datasets.py",
    "old_str": "# Load registry\nwith open('data/cell_benchmark_registry.json', 'r') as f:\n    registry = json.load(f)",
    "new_str": "# Load registry\nwith open('../data/cell_benchmark_registry.json', 'r') as f:\n    registry = json.load(f)"
  }
}
```


